// 解析 LINE webhook event（訊息或 postback），決定 T0（伺服器收訊時間，Asia/Taipei）
const body = $input.first().json.body || $input.first().json;
const ev = (body.events && body.events[0]) || {};
const msg = ev.message || {};
const pb = ev.postback || {};
const now = new Date(ev.timestamp || Date.now());
const t0 = new Date(now.getTime() + 8 * 3600 * 1000).toISOString().replace('Z', '+08:00');
return [{ json: {
  event_type: ev.type || null,          // 'message' | 'postback' | ...
  reply_token: ev.replyToken || null,
  source_user: (ev.source && ev.source.userId) || null,
  message_type: msg.type || null,       // 'image' | 'text' | ...
  message_id: msg.id || null,
  text: msg.type === 'text' ? (msg.text || '') : '',
  postback_data: pb.data || null,        // 例：action=half&meal_id=<encodeURIComponent>
  t0,
  raw_event: ev
} }];
// TODO: LINE 可在單一請求批次多個 events；此處只處理 events[0]。

// 組 Gemini 提示與回應 schema（完整版見 n8n/gemini-prompt.md）
const p = $('Parse LINE Event').item.json;
const prompt = [
  '你是營養估算助手。根據餐點照片與使用者備註，逐項列出食物、推估份量(克)與三大營養素。',
  '規則：1) 每項給 portion_g 與 0-1 信心度；2) 不確定就給區間中點並降低信心度；3) 只輸出 JSON。',
  '使用者備註：' + (p.text || '（無）')
].join('\n');
const schema = {
  type: 'object',
  properties: {
    items: { type: 'array', items: { type: 'object', properties: {
      name: { type: 'string' }, portion_g: { type: 'number' }, portion_confidence: { type: 'number' },
      carb_g: { type: 'number' }, net_carb_g: { type: 'number' }, protein_g: { type: 'number' },
      fat_g: { type: 'number' }, fiber_g: { type: 'number' }
    }, required: ['name','portion_g','carb_g','protein_g','fat_g'] } },
    totals: { type: 'object', properties: {
      carb_g: { type: 'number' }, net_carb_g: { type: 'number' }, protein_g: { type: 'number' },
      fat_g: { type: 'number' }, fiber_g: { type: 'number' } } },
    gi_est: { type: 'number' }, gl_est: { type: 'number' }, gi_confidence: { type: 'number' },
    eating_order: { type: 'string', enum: ['veg_first','carb_first','mixed','unknown'] },
    post_meal_activity: { type: 'string', enum: ['none','walk_10_15min','walk_30min+','unknown'] }
  },
  required: ['items','totals']
};
return [{ json: { prompt, schema } }];

