// 解析 Gemini 回應 → 套用個人常吃食物表覆蓋總碳水 → 組 meals 列
const p = $('Parse LINE Event').item.json;
const resp = $input.first().json;
let est = {};
try { est = JSON.parse(resp.candidates[0].content.parts[0].text); }
catch (e) { est = { items: [], totals: {}, _parse_error: String(e) }; }

// TODO: 讀 Google Sheets 的 personal_food_table，對 est.items[].name 做碳水覆蓋
const PERSONAL_TABLE = {};

function r1(x) { return x == null ? null : Math.round(x * 10) / 10; }
const totals = est.totals || {};
const confs = (est.items || []).map(i => i.portion_confidence).filter(x => typeof x === 'number');
const confidence = confs.length ? r1(confs.reduce((a, b) => a + b, 0) / confs.length) : 0.4;

return [{ json: {
  meal_id: p.t0,
  t0: p.t0,
  note: p.text || '',
  items_json: JSON.stringify(est.items || []),
  carb_g: r1(totals.carb_g),
  net_carb_g: r1(totals.net_carb_g ?? totals.carb_g),
  protein_g: r1(totals.protein_g),
  fat_g: r1(totals.fat_g),
  fiber_g: r1(totals.fiber_g),
  gi_est: r1(est.gi_est),
  gl_est: r1(est.gl_est),
  eating_order: est.eating_order || 'unknown',
  post_meal_activity: est.post_meal_activity || 'unknown',
  confidence,
  user_confirmed: false,
  image_url: ($('Archive Image to Drive').item.json.webViewLink) || '',
  source_user: p.source_user
} }];

