// 解析一鍵校正 postback：action=ok|half|double & meal_id=<encodeURIComponent>
const ev = $('Parse LINE Event').item.json;
const params = new URLSearchParams(ev.postback_data || '');
return [{ json: {
  action: params.get('action'),
  meal_id: params.get('meal_id')
} }];

// 依 action 回寫：ok → 只設 user_confirmed；half/double → 依比例縮放份量相關欄位
const action = $('Parse Postback').item.json.action;
const mealId = $('Parse Postback').item.json.meal_id;
const row = $json;  // Read meals Row 的匹配列

if (!row || !row.meal_id) {
  return [{ json: { meal_id: mealId, _not_found: true } }];
}

const factor = action === 'half' ? 0.5 : action === 'double' ? 2 : 1;
function scale(v) {
  const n = parseFloat(v);
  return Number.isFinite(n) ? Math.round(n * factor * 10) / 10 : v;
}

const out = { meal_id: row.meal_id, user_confirmed: true };

if (factor !== 1) {
  let items = [];
  try { items = JSON.parse(row.items_json || '[]'); } catch (e) {}
  items = items.map(it => ({
    ...it,
    portion_g: scale(it.portion_g), carb_g: scale(it.carb_g), net_carb_g: scale(it.net_carb_g),
    protein_g: scale(it.protein_g), fat_g: scale(it.fat_g), fiber_g: scale(it.fiber_g)
  }));
  out.items_json = JSON.stringify(items);
  out.carb_g = scale(row.carb_g);
  out.net_carb_g = scale(row.net_carb_g);
  out.protein_g = scale(row.protein_g);
  out.fat_g = scale(row.fat_g);
  out.fiber_g = scale(row.fiber_g);
  out.gl_est = scale(row.gl_est);   // GL 隨碳水縮放；GI 為強度性質不變
}
return [{ json: out }];

