// 解析 LibreView 匯出 CSV → cgm 列（時區正規化 Asia/Taipei，去重）
// 與 engine/cgm_coach/libre.py 邏輯一致；此為 n8n 端輕量版。
const csv = Buffer.from($binary.data.data, 'base64').toString('utf8');
const lines = csv.split(/\r?\n/).filter(Boolean);
const header = lines[1].split(',').map(s => s.replace(/^"|"$/g, '').trim());
const idx = (name) => header.indexOf(name);
const iTs = idx('Device Timestamp');
const iHist = idx('Historic Glucose mg/dL');
const iScan = idx('Scan Glucose mg/dL');
const iSerial = idx('Serial Number');
const out = [];
const seen = new Set();
for (let r = 2; r < lines.length; r++) {
  const cols = lines[r].split(',').map(s => s.replace(/^"|"$/g, '').trim());
  const g = cols[iHist] || cols[iScan];
  if (!g) continue;
  // TODO: 依匯出地區設定 dayfirst；此處假設 MM-DD-YYYY HH:MM
  const ts = new Date(cols[iTs]);
  if (isNaN(ts)) continue;
  const iso = new Date(ts.getTime() + 8 * 3600 * 1000).toISOString().replace('Z', '+08:00');
  const session = cols[iSerial] || 'unknown';
  const key = iso + '|' + session;
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ json: { ts: iso, glucose_mgdl: Number(g), sensor_session: session, source: 'libre' } });
}
return out;
